{"op":"add","path":"/root","value":"pricing-page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["pricing-header","billing-toggle","plans-grid","selection-confirmation"]}}
{"op":"add","path":"/elements/pricing-header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["pricing-title","pricing-intro"]}}
{"op":"add","path":"/elements/pricing-title","value":{"type":"Heading","props":{"text":"Simple pricing for every team","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/pricing-intro","value":{"type":"Text","props":{"text":"Start free, upgrade as you grow, and choose a plan that gives your entire team the tools it needs.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/billing-toggle","value":{"type":"Card","props":{"title":"Choose your billing cycle","description":"Save 20% when you choose annual billing."},"children":["billing-switch"]}}
{"op":"add","path":"/elements/billing-switch","value":{"type":"Switch","props":{"label":"Annual billing","description":"Pay once per year and save 20%.","checked":{"$bindState":"/billing/annual"}},"children":[]}}
{"op":"add","path":"/elements/plans-grid","value":{"type":"Grid","props":{"columns":"3","gap":"md"},"children":["plan-card"],"repeat":{"statePath":"/plans","key":"id"}}}
{"op":"add","path":"/state/billing","value":{}}
{"op":"add","path":"/state/billing/annual","value":false}
{"op":"add","path":"/state/plans","value":[]}
{"op":"add","path":"/state/plans/0","value":{"id":"free","name":"Free","description":"For individuals getting started with essential planning tools.","monthlyPrice":"$0","annualPrice":"$0","priceSuffix":"forever","badge":"Get started","features":["1 project with up to 3 collaborators","Unlimited tasks and boards","Basic templates","Community support"],"cta":"Start for free","ctaVariant":"outline"}}
{"op":"add","path":"/state/plans/1","value":{"id":"pro","name":"Pro","description":"For professionals who need advanced tools and more flexibility.","monthlyPrice":"$18","annualPrice":"$172","priceSuffix":"per month","badge":"Most popular","features":["Unlimited projects and collaborators","Advanced reporting and analytics","Custom fields and automations","Priority email support","20 GB file storage"],"cta":"Choose Pro","ctaVariant":"default"}}
{"op":"add","path":"/state/plans/2","value":{"id":"team","name":"Team","description":"For growing teams that need collaboration and centralized control.","monthlyPrice":"$36","annualPrice":"$346","priceSuffix":"per user, per month","badge":"Best for teams","features":["Everything in Pro","Roles and permissions","Shared team dashboards","SAML single sign-on","100 GB file storage","Dedicated support"],"cta":"Start with Team","ctaVariant":"secondary"}}
{"op":"add","path":"/elements/plan-card","value":{"type":"Card","props":{"title":{"$item":"name"},"description":{"$item":"description"}},"children":["plan-badge","plan-price","plan-billing-note","features-divider","features-list","plan-cta"]}}
{"op":"add","path":"/elements/plan-badge","value":{"type":"Badge","props":{"text":{"$item":"badge"},"variant":{"$cond":{"$state":"/billing/annual"},"$then":"outline","$else":"default"}},"children":[]}}
{"op":"add","path":"/elements/plan-price","value":{"type":"Text","props":{"text":{"$template":"${/plans/${$index}/monthlyPrice}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/plan-billing-note","value":{"type":"Text","props":{"text":{"$item":"priceSuffix"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/features-divider","value":{"type":"Separator","props":{},"children":[]}}
{"op":"add","path":"/elements/features-list","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"repeat":{"statePath":{"$item":"features"},"key":"feature"},"children":["feature-item"]}}
{"op":"add","path":"/elements/feature-item","value":{"type":"Text","props":{"text":{"$item":"feature"},"variant":"small"},"children":[]}}
{"op":"add","path":"/elements/plan-cta","value":{"type":"Button","props":{"label":{"$item":"cta"},"variant":{"$item":"ctaVariant"},"size":"lg"},"on":{"press":{"action":"setState","params":{"statePath":"/selectedPlan","value":{"$item":"name"}}}},"children":[]}}
{"op":"add","path":"/state/selectedPlan","value":""}
{"op":"add","path":"/elements/selection-confirmation","value":{"type":"Alert","props":{"title":"Plan selected","description":{"$template":"You selected the ${/selectedPlan} plan. Our team will guide you through the next steps."},"variant":"default"},"visible":{"$state":"/selectedPlan","not":true},"children":[]}}
